using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Microsoft.IdentityModel.Tokens;using TEKAManager.Core.DTOs;
namespace TEKAManager.API.Security;
public interface IJwtTokenService{string Create(UsuarioSesionDTO user);}
public class JwtTokenService(IConfiguration config):IJwtTokenService{public string Create(UsuarioSesionDTO user){var key=config["Jwt:Key"]??throw new InvalidOperationException("Falta Jwt:Key en configuración.");var claims=new[]{new Claim(JwtRegisteredClaimNames.Sub,user.UsuarioId.ToString()),new Claim(ClaimTypes.NameIdentifier,user.UsuarioId.ToString()),new Claim(ClaimTypes.Name,user.Username)};var creds=new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256);var token=new JwtSecurityToken(config["Jwt:Issuer"]??"TEKA",config["Jwt:Audience"]??"TEKA-Manager",claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:creds);return new JwtSecurityTokenHandler().WriteToken(token);}}
